function CommandShortcut({
  className,
  ...props
}: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="command-shortcut"
      className={cn(
        "ms-auto text-muted-foreground text-xs tracking-widest group-data-selected/command-item:text-accent-foreground",
        className,
