const Command = withGlass(CommandImplementation);

export {
  Command,
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
  CommandShortcut,
};

"use client";

import { cn } from "cn";
import type { ClipboardStatus } from "@/hooks/use-clipboard";
import {
  type IconInput,
  type IconNode,
  MorphIcon,
  type MorphIconProps,
} from "@/components/ui/morph-icon";

const copyShape: IconNode = [
  ["rect", { width: 14, height: 14, x: 8, y: 8, rx: 2, ry: 2 }],
  ["path", { d: "M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2" }],
];
const checkShape: IconNode = [["path", { d: "m20 6-11 11-5-5" }]];
const errorShape: IconNode = [["path", { d: "m18 6-12 12M6 6l12 12" }]];
const pendingShape: IconNode = [["path", { d: "M12 2a10 10 0 1 0 10 10" }]];

type CopyIconProps = Omit<
  MorphIconProps,
  "icon" | "from" | "to" | "progress"
> & {
  status?: ClipboardStatus;
  copied?: boolean;
  error?: boolean;
  pending?: boolean;
  idleIcon?: IconInput;
};

function CopyIcon({
  status,
  copied = false,
  error = false,
  pending = false,
  className,
  idleIcon = copyShape,
  ...props
}: CopyIconProps) {
  let state: ClipboardStatus = status ?? "idle";
  if (status === undefined) {
    if (error) state = "error";
    else if (pending) state = "pending";
    else if (copied) state = "copied";
  }
  const icon = {
    idle: idleIcon,
    pending: pendingShape,
    copied: checkShape,
    error: errorShape,
  }[state];
  return (
    <MorphIcon
      icon={icon}
      data-slot="copy-icon"
      data-copy-state={state}
      className={cn(
        state === "pending" && "animate-spin motion-reduce:animate-none",
        state === "copied" && "text-primary",
        state === "error" && "text-destructive",
        className,
      )}
      {...props}
    />
  );
}

export type { CopyIconProps };
export { CopyIcon };

"use client";

import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva } from "class-variance-authority";
import { cn } from "cn";
import type { ReactNode } from "react";
import { type ClipboardOptions, useClipboard } from "@/hooks/use-clipboard";
import { CopyIcon } from "@/components/ui/copy-icon";

type CopyTextProps = Omit<
  ButtonPrimitive.Props,
  "children" | "onCopy" | "value" | "variant" | "size"
> &
  ClipboardOptions & {
    children: ReactNode;
    value?: string;
    variant?: "default" | "muted";
    size?: "sm" | "default";
    truncate?: boolean;
    iconVisibility?: "hover" | "always";
  };

const copyTextVariants = cva(
  "group/copy-text inline-flex min-w-0 max-w-full select-text items-center gap-1.5 rounded-sm border-0 bg-transparent p-0 align-baseline font-normal outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:cursor-not-allowed disabled:opacity-50 data-[copy-status=pending]:disabled:opacity-100",
  {
    variants: {
      variant: {
        default: "text-foreground",
        muted:
          "text-muted-foreground hover:text-foreground focus-visible:text-foreground",
      },
      size: {
        default: "text-sm leading-5",
        sm: "text-xs leading-4",
      },
    },
    defaultVariants: { variant: "default", size: "default" },
  },
);

function CopyText({
  children,
  value,
  variant = "default",
  size = "default",
  truncate = true,
  iconVisibility = "hover",
  disabled = false,
  resetDelay,
  onCopy,
  onCopyError,
  feedback,
  labels,
  onClick,
  className,
  ...props
}: CopyTextProps) {
  const text = value ?? (typeof children === "string" ? children : null);
  if (text === null)
    throw new Error("CopyText requires value when children is not a string.");
  const { status, message, copy } = useClipboard(text, {
    disabled,
    resetDelay,
    onCopy,
    onCopyError,
    feedback,
    labels,
  });
  return (
    <ButtonPrimitive
      {...props}
      type="button"
      disabled={disabled || status === "pending"}
      data-slot="copy-text"
      data-copy-status={status}
      aria-busy={status === "pending"}
      aria-label={props["aria-label"] ?? labels?.copy ?? `Copy ${text}`}
      className={cn(copyTextVariants({ variant, size }), className)}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) void copy();
      }}
    >
      <code className={cn("min-w-0 font-mono", truncate && "truncate")}>
        {children}
      </code>
      <span
        aria-hidden="true"
        className={cn(
          "relative inline-flex size-3.5 shrink-0 items-center justify-center transition-opacity motion-reduce:transition-none",
          status === "idle" &&
            iconVisibility === "hover" &&
            "opacity-0 group-focus-within/copy-text:opacity-100 group-focus-within:opacity-100 group-hover/copy-text:opacity-100 group-hover:opacity-100 [@media(hover:none)]:opacity-100",
        )}
      >
        <CopyIcon status={status} className="size-3.5" />
      </span>
      <span role="status" className="sr-only">
        {status === "idle" ? "" : message}
      </span>
    </ButtonPrimitive>
  );
}

export type { CopyTextProps };

export { CopyText, copyTextVariants };

"use client";

import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { cn } from "cn";
import {
  ArrowDown,
  ArrowUp,
  ChevronsUpDown,
  EyeOff,
  Info,
  X,
} from "lucide-react";
import { useDataTableContext } from "@/components/ui/data-table/context";
import { menuWidth } from "@/components/ui/data-table/menu";
import type { NormalizedColumn, SortOrder } from "@/components/ui/data-table/types";

function SortIcon({ order }: { order: SortOrder | undefined }) {
  if (order === "asc") return <ArrowUp />;
  if (order === "desc") return <ArrowDown />;
  return <ChevronsUpDown className="opacity-50" />;
}

function HeaderTitle({ column }: { column: NormalizedColumn<unknown> }) {
  const tooltip = column.config.tooltip;
  return (
    <span className="inline-flex min-w-0 shrink-0 items-center gap-1">
      <span className="min-w-0 truncate">{column.title}</span>
      {tooltip && (
        <Tooltip>
          <TooltipTrigger
            render={<span className="inline-flex text-muted-foreground" />}
          >
            <Info className="size-3.5" />
          </TooltipTrigger>
          <TooltipContent>{tooltip}</TooltipContent>
        </Tooltip>
      )}
    </span>
  );
}

/** Column title with a sort and hide menu for sortable columns. */
export function DataTableColumnHeader({
  column,
  className,
}: {
  column: NormalizedColumn<unknown>;
  className?: string;
}) {
  const table = useDataTableContext();
  const { labels } = table;
  if (!column.sortable || table.features.dragSort)
    return (
      <div className={cn("flex items-center", className)}>
        <HeaderTitle column={column} />
      </div>
    );
  const order = table.state.sort.find((item) => item.key === column.id)?.order;
  const sortBy = (next: SortOrder | undefined) =>
    table.setSort(next ? [{ key: column.id, order: next }] : []);
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            variant="ghost"
            size="sm"
            className={cn(
              "-ms-2 h-8 max-w-full gap-1 px-2 font-medium data-popup-open:bg-accent",
              className,
            )}
          />
        }
      >
        <HeaderTitle column={column} />
        <SortIcon order={order} />
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" className={menuWidth}>
        <DropdownMenuGroup>
          <DropdownMenuLabel>{column.title}</DropdownMenuLabel>
        </DropdownMenuGroup>
        <DropdownMenuItem onClick={() => sortBy("asc")}>
          <ArrowUp />
          {labels.sortAscending}
        </DropdownMenuItem>
        <DropdownMenuItem onClick={() => sortBy("desc")}>
          <ArrowDown />
          {labels.sortDescending}
        </DropdownMenuItem>
        {order && (
          <DropdownMenuItem onClick={() => sortBy(undefined)}>
            <X />
            {labels.clearSorting}
          </DropdownMenuItem>
        )}
        <DropdownMenuSeparator />
        <DropdownMenuItem
          onClick={() =>
            table.setColumnState((current) => ({
              ...current,
              visibility: { ...current.visibility, [column.id]: false },
            }))
          }
        >
          <EyeOff />
          {labels.hideColumn}
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

"use client";

import { Badge } from "@/components/ui/badge";
import { CopyText } from "@/components/ui/copy-text";
import { LongText } from "@/components/ui/long-text";
import type { ReactNode } from "react";
import { getPath, isEmptyValue, toTime } from "@/components/ui/data-table/engine";
import type { DataTableLabels } from "@/components/ui/data-table/labels";
import type {
  DataTableColumn,
  DataTableDataColumn,
  DataTableDisplayColumn,
  DataTableOption,
  DataTableSearchType,
  DataTableValueType,
  NormalizedColumn,
} from "@/components/ui/data-table/types";

type Format = DataTableDataColumn<unknown>["format"];

interface FormatContext {
  readonly locale: string | undefined;
  readonly labels: DataTableLabels;
  readonly format: Format;
  readonly valueEnum?: readonly DataTableOption[];
}

function formatNumber(value: unknown, locale?: string, options?: Format) {
  const number = Number(value);
  if (Number.isNaN(number)) return String(value);
  return new Intl.NumberFormat(locale, options).format(number);
}

// toTime reads a calendar date as local midnight, so it formats as that day.
function formatDate(value: unknown, locale?: string, options?: Format) {
  const time = toTime(value);
  if (time === undefined) return String(value);
  return new Intl.DateTimeFormat(locale, options).format(time);
}

function optionLabel(value: unknown, options?: readonly DataTableOption[]) {
  return options?.find((option) => option.value === String(value));
}

/** Plain text of a value, shared by cells, chips and CSV exports. */
const textFormatters: Record<
  DataTableValueType,
  (value: unknown, context: FormatContext) => string
> = {
  text: (value) => String(value),
  number: (value, { locale, format }) => formatNumber(value, locale, format),
  money: (value, { locale, format }) =>
    formatNumber(value, locale, {
      style: "currency",
      currency: "USD",
      ...format,
    }),
  percent: (value, { locale, format }) =>
    formatNumber(Number(value) / 100, locale, {
      style: "percent",
      maximumFractionDigits: 2,
      ...format,
    }),
  date: (value, { locale, format }) =>
    formatDate(value, locale, format ?? { dateStyle: "medium" }),
  datetime: (value, { locale, format }) =>
    formatDate(
      value,
      locale,
      format ?? { dateStyle: "medium", timeStyle: "short" },
    ),
  enum: (value, { valueEnum }) => {
    const label = optionLabel(value, valueEnum)?.label;
    return typeof label === "string" ? label : String(value);
  },
  boolean: (value, { labels }) => (value ? labels.yes : labels.no),
};

export function formatValue(
  valueType: DataTableValueType,
  value: unknown,
  context: FormatContext,
) {
  if (isEmptyValue(value)) return "";
  return textFormatters[valueType](value, context);
}

function renderEnum(value: unknown, options?: readonly DataTableOption[]) {
  const option = optionLabel(value, options);
  if (!option) return String(value);
  return <Badge variant={option.color ?? "secondary"}>{option.label}</Badge>;
}

const defaultSearchTypes: Record<DataTableValueType, DataTableSearchType> = {
  text: "text",
  number: "numberRange",
  money: "numberRange",
  percent: "numberRange",
  date: "dateRange",
  datetime: "datetimeRange",
  enum: "select",
  boolean: "boolean",
};

function textOf(node: ReactNode, fallback: string) {
  return typeof node === "string" || typeof node === "number"
    ? String(node)
    : fallback;
}

/** Applies defaults: `valueEnum` implies an enum column with a quick filter. */
export function normalizeColumns<TData>(
  columns: readonly DataTableColumn<TData>[],
  labels: DataTableLabels,
): NormalizedColumn<TData>[] {
  const locale = labels.locale;
  return columns.map((config) => {
    if (config.key === undefined) {
      const display = config as DataTableDisplayColumn<TData>;
      return {
        id: display.id,
        title: display.title ?? "",
        titleText: textOf(display.title, display.id),
        valueType: "text",
        display: true,
        config,
        sortable: false,
        keyword: false,
        filter: false,
        searchOnly: false,
        renderCell: display.render,
        getValue: () => undefined,
        exportText: () => "",
      } satisfies NormalizedColumn<TData>;
    }
    const column = config as DataTableDataColumn<TData>;
    const key = String(column.key);
    const id = column.id ?? key;
    const valueType: DataTableValueType =
      column.valueType ?? (column.valueEnum ? "enum" : "text");
    const context: FormatContext = {
      locale,
      labels,
      format: column.format,
      valueEnum: column.valueEnum,
    };
    const getValue = (row: TData) => getPath(row, key);
    const searchConfig =
      typeof column.search === "object" ? column.search : undefined;
    const search =
      column.search || column.searchOnly
        ? {
            ...searchConfig,
            type: searchConfig?.type ?? defaultSearchTypes[valueType],
            options: searchConfig?.options ?? column.valueEnum,
          }
        : undefined;
    const render = column.render as
      | ((value: unknown, row: TData, index: number) => ReactNode)
      | undefined;
    const exportValue = column.exportValue as
      | ((value: unknown, row: TData) => string)
      | undefined;
    function renderCell(row: TData, index: number): ReactNode {
      const value = getValue(row);
      if (render) return render(value, row, index);
      if (isEmptyValue(value))
        return <span className="text-muted-foreground">-</span>;
      if (valueType === "enum") return renderEnum(value, column.valueEnum);
      const text = formatValue(valueType, value, context);
      if (column.copyable) return <CopyText>{text}</CopyText>;
      if (column.ellipsis) return <LongText>{text}</LongText>;
      return text;
    }
    return {
      id,
      key,
      title: column.title ?? key,
      titleText: textOf(column.title, key),
      valueType,
      valueEnum: column.valueEnum,
      display: false,
      config,
      search,
      sortable: !!column.sortable || !!column.sorter,
      keyword: !!column.keyword,
      filter: column.filter ?? (valueType === "enum" && !!column.valueEnum),
      searchOnly: !!column.searchOnly,
      renderCell,
      getValue,
      exportText: (row) => {
        const value = getValue(row);
        if (exportValue) return exportValue(value, row);
        return formatValue(valueType, value, context);
      },
    } satisfies NormalizedColumn<TData>;
  });
}

/** A fixed-width column for plugin controls such as checkboxes and handles. */
export function utilityColumn<TData>(
  id: string,
  renderCell: (row: TData, index: number) => ReactNode,
  title: ReactNode = "",
): NormalizedColumn<TData> {
  return {
    id,
    title,
    titleText: "",
    valueType: "text",
    display: true,
    utility: true,
    config: { id, width: 40, render: () => null },
    sortable: false,
    keyword: false,
    filter: false,
    searchOnly: false,
    getValue: () => undefined,
    exportText: () => "",
    renderCell,
  };
}

"use client";

import { ScrollArea as ScrollAreaPrimitive } from "@base-ui/react/scroll-area";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Empty,
  EmptyContent,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty";
import { Skeleton } from "@/components/ui/skeleton";
import { useIsMobile } from "@/hooks/use-mobile";
import { cn } from "cn";
import { CircleAlert, Inbox, LoaderCircle } from "lucide-react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import {
  type ComponentProps,
  type CSSProperties,
  Fragment,
  type PointerEvent,
  type ReactNode,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { DataTableColumnHeader } from "@/components/ui/data-table/column-header";
import { useDataTableContext } from "@/components/ui/data-table/context";
import type {
  DataTableDensity,
  DataTableInstance,
  NormalizedColumn,
} from "@/components/ui/data-table/types";

/** Beyond this many rows, layout animation costs more than it shows. */
const ANIMATED_ROW_LIMIT = 100;

const densityPadding: Record<DataTableDensity, string> = {
  compact: "py-1.5",
  default: "py-2.5",
  comfortable: "py-4",
};

const alignClass = {
  start: "text-start",
  center: "text-center",
  end: "text-end",
};

type Offsets = { start: Record<string, number>; end: Record<string, number> };

function pinSide(
  table: DataTableInstance<unknown>,
  column: NormalizedColumn<unknown>,
) {
  if (column.utility) return "start";
  return table.columnState.pinning[column.id];
}

/** Sticky offsets from measured header widths, so pinned columns stack. */
function usePinnedOffsets(
  table: DataTableInstance<unknown>,
  headers: React.RefObject<Map<string, HTMLTableCellElement>>,
) {
  const [offsets, setOffsets] = useState<Offsets>({ start: {}, end: {} });
  const columns = table.visibleColumns;
  useLayoutEffect(() => {
    const next: Offsets = { start: {}, end: {} };
    let start = 0;
    for (const column of columns) {
      if (pinSide(table, column) !== "start") continue;
      next.start[column.id] = start;
      start += headers.current.get(column.id)?.offsetWidth ?? 0;
    }
    let end = 0;
    for (const column of [...columns].reverse()) {
      if (pinSide(table, column) !== "end") continue;
      next.end[column.id] = end;
      end += headers.current.get(column.id)?.offsetWidth ?? 0;
    }
    setOffsets((current) =>
      JSON.stringify(current) === JSON.stringify(next) ? current : next,
    );
  });
  return offsets;
}

/**
 * Marks the scroller while content hides under pinned columns, so their
 * shadows only show when there is something to separate.
 */
function useScrollEdges(scroller: React.RefObject<HTMLDivElement | null>) {
  useLayoutEffect(() => {
    const element = scroller.current;
    if (!element) return;
    const update = () => {
      const offset = Math.abs(element.scrollLeft);
      const max = element.scrollWidth - element.clientWidth;
      element.toggleAttribute("data-scrolled-start", offset > 0);
      element.toggleAttribute("data-scrolled-end", offset < max - 1);
    };
    update();
    element.addEventListener("scroll", update, { passive: true });
    const observer = new ResizeObserver(update);
    observer.observe(element);
    if (element.firstElementChild) observer.observe(element.firstElementChild);
    return () => {
      element.removeEventListener("scroll", update);
      observer.disconnect();
    };
  }, [scroller]);
}

function cellLayout(
  table: DataTableInstance<unknown>,
  column: NormalizedColumn<unknown>,
  offsets: Offsets,
) {
  const side = pinSide(table, column);
  const width = table.columnState.widths[column.id] ?? column.config.width;
  const style: CSSProperties = {};
  if (width !== undefined) {
    style.width = width;
    style.minWidth = width;
    style.maxWidth = width;
  } else if (column.config.minWidth !== undefined) {
    style.minWidth = column.config.minWidth;
  }
  if (side === "start") style.insetInlineStart = offsets.start[column.id] ?? 0;
  if (side === "end") style.insetInlineEnd = offsets.end[column.id] ?? 0;
  const columns = table.visibleColumns;
  const lastStart = [...columns]
    .reverse()
    .find((entry) => pinSide(table, entry) === "start");
  const firstEnd = columns.find((entry) => pinSide(table, entry) === "end");
  return {
    style,
    pinned: !!side,
    className: cn(
      side && "sticky z-10",
      lastStart === column &&
        "after:pointer-events-none after:absolute after:inset-y-0 after:-end-3 after:w-3 after:bg-linear-to-r after:from-foreground/8 after:to-transparent after:opacity-0 after:transition-opacity group-data-[scrolled-start]/scroller:after:opacity-100 dark:after:from-black/50",
      firstEnd === column &&
        "before:pointer-events-none before:absolute before:inset-y-0 before:-start-3 before:w-3 before:bg-linear-to-l before:from-foreground/8 before:to-transparent before:opacity-0 before:transition-opacity group-data-[scrolled-end]/scroller:before:opacity-100 dark:before:from-black/50",
      column.config.align && alignClass[column.config.align],
      column.config.className,
    ),
  };
}

function ResizeHandle({
  table,
  column,
}: {
  table: DataTableInstance<unknown>;
  column: NormalizedColumn<unknown>;
}) {
  function start(event: PointerEvent<HTMLDivElement>) {
    event.preventDefault();
    const cell = event.currentTarget.parentElement;
    const startX = event.clientX;
    const startWidth = cell?.offsetWidth ?? 0;
    const direction = document.dir === "rtl" ? -1 : 1;
    const move = (moveEvent: globalThis.PointerEvent) => {
      const width = Math.max(
        48,
        Math.round(startWidth + (moveEvent.clientX - startX) * direction),
      );
      table.setColumnState((current) => ({
        ...current,
        widths: { ...current.widths, [column.id]: width },
      }));
    };
    const stop = () => {
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", stop);
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", stop);
  }
  return (
    <div
      aria-hidden
      title={table.labels.resizeColumn}
      onPointerDown={start}
      className="absolute inset-y-2 -end-px w-1 cursor-col-resize touch-none rounded-full bg-border opacity-0 transition-opacity hover:opacity-100 group-hover/head:opacity-60"
    />
  );
}

function StatusRow({
  colSpan,
  children,
}: {
  colSpan: number;
  children: ReactNode;
}) {
  return (
    <tr>
      <td colSpan={colSpan} className="p-0">
        {children}
      </td>
    </tr>
  );
}

export function DataTableStatus({
  error,
  onRetry,
  title,
}: {
  error?: boolean;
  onRetry?: () => void;
  title: ReactNode;
}) {
  const table = useDataTableContext();
  return (
    <Empty role="status" className="min-h-48 border-0 py-10">
      <EmptyHeader>
        <EmptyMedia variant="icon">
          {error ? <CircleAlert /> : <Inbox />}
        </EmptyMedia>
        <EmptyTitle>{title}</EmptyTitle>
      </EmptyHeader>
      {onRetry && (
        <EmptyContent>
          <Button variant="outline" size="sm" onClick={onRetry}>
            {table.labels.retry}
          </Button>
        </EmptyContent>
      )}
    </Empty>
  );
}

function useAnimatedRows(table: DataTableInstance<unknown>) {
  const reduced = useReducedMotion();
  return (
    !reduced &&
    !table.features.virtual &&
    !table.features.dragSort &&
    table.rows.length <= ANIMATED_ROW_LIMIT
  );
}

/** Virtual window over the rows from the scroll container's position. */
function useVirtualWindow(
  table: DataTableInstance<unknown>,
  scroller: React.RefObject<HTMLDivElement | null>,
) {
  const virtual = table.features.virtual;
  const [view, setView] = useState({ top: 0, height: 800 });
  useLayoutEffect(() => {
    const element = scroller.current;
    if (!virtual || !element) return;
    const update = () =>
      setView({ top: element.scrollTop, height: element.clientHeight || 800 });
    update();
    element.addEventListener("scroll", update, { passive: true });
    const observer = new ResizeObserver(update);
    observer.observe(element);
    return () => {
      element.removeEventListener("scroll", update);
      observer.disconnect();
    };
  }, [virtual, scroller]);
  if (!virtual)
    return { start: 0, end: table.rows.length, before: 0, after: 0 };
  const { rowHeight, overscan } = virtual;
  const start = Math.max(0, Math.floor(view.top / rowHeight) - overscan);
  const end = Math.min(
    table.rows.length,
    Math.ceil((view.top + view.height) / rowHeight) + overscan,
  );
  return {
    start,
    end,
    before: start * rowHeight,
    after: (table.rows.length - end) * rowHeight,
  };
}

function DataRows({
  table,
  offsets,
  scroller,
}: {
  table: DataTableInstance<unknown>;
  offsets: Offsets;
  scroller: React.RefObject<HTMLDivElement | null>;
}) {
  const animated = useAnimatedRows(table);
  const range = useVirtualWindow(table, scroller);
  const columns = table.visibleColumns;
  const padding = densityPadding[table.density];
  const rowRenderer = table.plugins.find((plugin) => plugin.renderRow);
  const afterRenderers = table.plugins.filter(
    (plugin) => plugin.renderAfterRow,
  );
  const rows = table.rows.slice(range.start, range.end).map((row, offset) => {
    const index = range.start + offset;
    const id = table.getRowId(row, index);
    const selected = table.selection?.isSelected(id);
    const cells = columns.map((column) => {
      const layout = cellLayout(table, column, offsets);
      return (
        <td
          key={column.id}
          data-slot="data-table-cell"
          style={layout.style}
          className={cn(
            "whitespace-nowrap px-3 align-middle has-[[role=checkbox]]:pe-0",
            padding,
            layout.className,
            layout.pinned && "bg-inherit",
          )}
        >
          {column.renderCell(row, index)}
        </td>
      );
    });
    const rowProps = {
      "data-state": selected ? "selected" : undefined,
      className:
        "group/row border-b bg-background hover:bg-muted data-[state=selected]:bg-accent",
    } as ComponentProps<"tr">;
    const content = rowRenderer?.renderRow ? (
      rowRenderer.renderRow(
        { row, id, index, rowProps, children: cells },
        table,
      )
    ) : (
      <motion.tr
        key={id}
        {...(rowProps as object)}
        layout={animated ? "position" : false}
        initial={animated ? { opacity: 0, y: 6 } : false}
        animate={{ opacity: 1, y: 0 }}
        exit={
          animated ? { opacity: 0, transition: { duration: 0.12 } } : undefined
        }
        transition={{ type: "spring", stiffness: 500, damping: 40 }}
      >
        {cells}
      </motion.tr>
    );
    const after = afterRenderers.map((plugin) => (
      <AnimatePresence key={`${id}-${plugin.name}`} initial={false}>
        {plugin.renderAfterRow?.(row, id, table)}
      </AnimatePresence>
    ));
    if (after.length === 0 && !rowRenderer) return content;
    return (
      <Fragment key={id}>
        {content}
        {after}
      </Fragment>
    );
  });
  const spacer = (height: number, key: string) =>
    height > 0 && (
      <tr key={key} aria-hidden style={{ height }}>
        <td colSpan={columns.length} />
      </tr>
    );
  const body = (
    <>
      {spacer(range.before, "before")}
      {animated ? (
        <AnimatePresence initial={false} mode="popLayout">
          {rows}
        </AnimatePresence>
      ) : (
        rows
      )}
      {spacer(range.after, "after")}
    </>
  );
  return table.plugins.reduce<ReactNode>(
    (children, plugin) =>
      plugin.wrapBody ? plugin.wrapBody(children, table) : children,
    body,
  );
}

function SkeletonRows({ table }: { table: DataTableInstance<unknown> }) {
  const count = Math.min(table.state.pageSize, 8);
  return Array.from({ length: count }, (_, index) => (
    // biome-ignore lint/suspicious/noArrayIndexKey: placeholders have no identity.
    <tr key={index} className="border-b">
      {table.visibleColumns.map((column) => (
        <td
          key={column.id}
          className={cn("px-3", densityPadding[table.density])}
        >
          <Skeleton className="h-4 w-full max-w-40" />
        </td>
      ))}
    </tr>
  ));
}

function TableView({ className }: { className?: string }) {
  const table = useDataTableContext();
  const headers = useRef(new Map<string, HTMLTableCellElement>());
  const scroller = useRef<HTMLDivElement>(null);
  const offsets = usePinnedOffsets(table, headers);
  useScrollEdges(scroller);
  const columns = table.visibleColumns;
  const firstLoad = table.loading && table.rows.length === 0;
  let status: ReactNode = null;
  if (table.error)
    status = (
      <DataTableStatus
        error
        title={table.labels.loadFailed}
        onRetry={table.reload}
      />
    );
  else if (!table.loading && table.rows.length === 0)
    status = <DataTableStatus title={table.labels.noData} />;
  return (
    // Base UI scrollbars stay visible, unlike overlay scrollbars on macOS.
    <ScrollAreaPrimitive.Root
      data-slot="data-table-scroll-area"
      className={cn(
        "relative flex min-h-0 flex-col overflow-hidden",
        className,
      )}
    >
      <ScrollAreaPrimitive.Viewport
        ref={scroller}
        data-slot="data-table-scroller"
        className="group/scroller min-h-0 flex-1 overscroll-x-contain rounded-[inherit] outline-none focus-visible:ring-3 focus-visible:ring-ring/50"
      >
        <table
          data-slot="data-table"
          aria-busy={table.loading}
          className="w-full caption-bottom border-separate border-spacing-0 text-sm [&_td]:border-b [&_tr:last-child_td]:border-b-0"
        >
          <thead className="sticky top-0 z-20 bg-background">
            <tr>
              {columns.map((column) => {
                const layout = cellLayout(table, column, offsets);
                const sorted = table.state.sort.find(
                  (item) => item.key === column.id,
                );
                let ariaSort: "ascending" | "descending" | "none" | undefined;
                if (column.sortable)
                  ariaSort = sorted
                    ? ({ asc: "ascending", desc: "descending" } as const)[
                        sorted.order
                      ]
                    : "none";
                return (
                  <th
                    key={column.id}
                    ref={(node) => {
                      if (node) headers.current.set(column.id, node);
                      else headers.current.delete(column.id);
                    }}
                    aria-sort={ariaSort}
                    style={layout.style}
                    className={cn(
                      "group/head h-11 whitespace-nowrap border-b bg-background px-3 text-start align-middle font-medium text-muted-foreground has-[[role=checkbox]]:pe-0",
                      layout.className,
                      column.config.align && alignClass[column.config.align],
                    )}
                  >
                    {column.display ? (
                      column.title
                    ) : (
                      <DataTableColumnHeader
                        column={column}
                        className={cn(
                          column.config.align === "end" && "ms-auto",
                        )}
                      />
                    )}
                    {table.features.resizable && !column.utility && (
                      <ResizeHandle table={table} column={column} />
                    )}
                  </th>
                );
              })}
            </tr>
          </thead>
          <tbody
            data-slot="data-table-body"
            className={cn(
              "transition-opacity",
              table.loading && !firstLoad && "pointer-events-none opacity-60",
            )}
          >
            {firstLoad && <SkeletonRows table={table} />}
            {!firstLoad && !status && (
              <DataRows table={table} offsets={offsets} scroller={scroller} />
            )}
            {status && <StatusRow colSpan={columns.length}>{status}</StatusRow>}
          </tbody>
        </table>
      </ScrollAreaPrimitive.Viewport>
      {table.loading && !firstLoad && (
        <div
          role="status"
          aria-label={table.labels.loading}
          className="pointer-events-none absolute inset-0 grid place-items-center"
        >
          <LoaderCircle className="size-5 animate-spin text-muted-foreground" />
        </div>
      )}
      <TableScrollbar orientation="horizontal" />
      <TableScrollbar orientation="vertical" />
      <ScrollAreaPrimitive.Corner />
    </ScrollAreaPrimitive.Root>
  );
}

function TableScrollbar({
  orientation,
}: {
  orientation: "horizontal" | "vertical";
}) {
  return (
    <ScrollAreaPrimitive.Scrollbar
      orientation={orientation}
      className="z-30 flex touch-none select-none p-0.5 opacity-70 transition-opacity hover:opacity-100 data-[orientation=horizontal]:h-2.5 data-[orientation=vertical]:w-2.5 data-[orientation=horizontal]:flex-col"
    >
      <ScrollAreaPrimitive.Thumb className="flex-1 rounded-full bg-muted-foreground/40 hover:bg-muted-foreground/60" />
    </ScrollAreaPrimitive.Scrollbar>
  );
}

/** Narrow screens show each row as a card of title and value pairs. */
function CardView({ className }: { className?: string }) {
  const table = useDataTableContext();
  const reduced = useReducedMotion();
  const columns = table.visibleColumns.filter((column) => !column.utility);
  const primary = columns.find((column) => column.config.primary) ?? columns[0];
  const rest = columns.filter((column) => column !== primary);
  let status: ReactNode = null;
  if (table.error)
    status = (
      <DataTableStatus
        error
        title={table.labels.loadFailed}
        onRetry={table.reload}
      />
    );
  else if (!table.loading && table.rows.length === 0)
    status = <DataTableStatus title={table.labels.noData} />;
  return (
    <div
      data-slot="data-table-cards"
      aria-busy={table.loading}
      className={cn("min-h-0 space-y-2 overflow-auto", className)}
    >
      {status}
      {table.loading &&
        table.rows.length === 0 &&
        Array.from({ length: 4 }, (_, index) => (
          // biome-ignore lint/suspicious/noArrayIndexKey: placeholders have no identity.
          <Skeleton key={index} className="h-24 w-full rounded-xl" />
        ))}
      <AnimatePresence initial={false} mode="popLayout">
        {table.rows.map((row, index) => {
          const id = table.getRowId(row, index);
          const selected = table.selection?.isSelected(id) ?? false;
          return (
            <motion.div
              key={id}
              layout={reduced ? false : "position"}
              initial={reduced ? false : { opacity: 0, y: 6 }}
              animate={{ opacity: 1, y: 0 }}
              exit={reduced ? undefined : { opacity: 0 }}
              data-state={selected ? "selected" : undefined}
              className="rounded-xl border bg-card p-3 text-sm data-[state=selected]:bg-accent"
            >
              <div className="mb-2 flex items-center gap-2 font-medium">
                {table.selection && (
                  <Checkbox
                    aria-label={table.labels.selectRow}
                    checked={selected}
                    disabled={table.selection.isDisabled(row)}
                    onCheckedChange={() => table.selection?.toggle(id, row)}
                  />
                )}
                <div className="min-w-0 flex-1 truncate">
                  {primary?.renderCell(row, index)}
                </div>
              </div>
              <dl className="grid grid-cols-[auto_1fr] gap-x-3 gap-y-1.5">
                {rest.map((column) => (
                  <div key={column.id} className="contents">
                    <dt className="text-muted-foreground">{column.title}</dt>
                    <dd className="min-w-0 text-end">
                      {column.renderCell(row, index)}
                    </dd>
                  </div>
                ))}
              </dl>
              {table.plugins.map(
                (plugin) =>
                  plugin.renderAfterRow && (
                    <table key={plugin.name} className="mt-2 w-full">
                      <tbody>
                        <AnimatePresence initial={false}>
                          {plugin.renderAfterRow(row, id, table)}
                        </AnimatePresence>
                      </tbody>
                    </table>
                  ),
              )}
            </motion.div>
          );
        })}
      </AnimatePresence>
    </div>
  );
}

