      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className={menuWidth}>
        <DropdownMenuGroup>
          <DropdownMenuLabel>{labels.export}</DropdownMenuLabel>
          <DropdownMenuItem onClick={() => save(table.rows)}>
            {labels.exportPage}
          </DropdownMenuItem>
          <DropdownMenuItem
            onClick={async () => save(await table.getAllRows())}
          >
            {labels.exportAll}
          </DropdownMenuItem>
          {table.selection && (
            <DropdownMenuItem
              disabled={selected.length === 0}
              onClick={() => save(selected)}
            >
              {labels.exportSelected}
            </DropdownMenuItem>
          )}
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

